fn=r'''
function openSourceExplorer49(){
  const root=$('#modalRoot');let activeRoot=null,current=null,folders=[],files=[],history=[];let staged=[...state.intake.sources];const checked=new Set();const initialKeys=state.intake.sources.map(sourceKey).sort().join('\n');
  root.innerHTML=`<div class="modalback"><div class="modal pick49"><div class="modalhead"><div><h3>Add locations</h3><div class="subtle">Choose a location, select the whole volume or browse into folders, then add selected sources to the project.</div></div><button class="close" id="x">×</button></div><div class="pick49-grid"><aside class="pick49-pane pick49-left"><div class="pick49-title">Locations</div><div class="pick49-list" id="placesList"></div></aside><section class="pick49-pane pick49-center"><div class="pick49-toolbar"><button class="btn small" id="up" disabled>↑ Up</button><button class="btn small" id="rescan">↻ Rescan</button><div class="pick49-path" id="path">Select a location</div><button class="btn pick49-add" id="addChecked" disabled>＋ Add to project</button></div><div class="pick49-browser" id="browserList"><div class="pick49-empty"><strong>Select a location</strong>The selected volume appears here first. Check it to add the whole volume, or click its name to browse folders.</div></div><div class="pick49-status"><strong id="statusText">Nothing selected</strong><span id="itemCount">0 items</span></div></section><aside class="pick49-pane pick49-right"><div class="pick49-selected-head"><strong>Added to project <span class="badge" id="selectedCount">0</span></strong><div class="subtle">Click a source tile to add an optional note.</div></div><div class="pick49-selected" id="selectedList"></div><div class="pick49-actions"><button class="btn primary" id="saveLocations">Save selections</button><button class="btn" id="cancelLocations">Cancel</button></div></aside></div></div></div>`;
  const sourcePath=x=>typeof x==='string'?x:(x.path||x.locator||sourceDisplay(x));const sourceNote=x=>typeof x==='object'&&x?String(x.note||''):'';const makePathSource=path=>({source_type:'wsl_path',path,operator_label:path.split('/').filter(Boolean).pop()||path,note:''});const hasUnsaved=()=>staged.map(sourceKey).sort().join('\n')!==initialKeys;const close=(force=false)=>{if(!force&&hasUnsaved()&&!confirm('Discard the source selections you have not saved?'))return false;root.innerHTML='';return true};$('#x').onclick=()=>close(false);
  function stagedHasPath(path){return staged.some(x=>sourcePath(x)===path)}
  function renderPlaces(){let html='';if(!STATIC_PREVIEW&&state.fsLive)html+=state.roots.map(r=>`<button class="pick49-location ${activeRoot?.path===r.path?'active':''}" data-place="${esc(r.path)}">▣ ${esc(r.label)}<small>${esc(r.path)}</small></button>`).join('');if(HAS_DIRECTORY_PICKER||HAS_DIRECTORY_INPUT)html+=`<button class="pick49-location" id="devicePlace">▯ This device<small>Choose a browser-authorized folder</small></button>`;if(!html)html='<div class="pick49-static"><strong>No accessible locations</strong><small>Server-backed storage is not available on this host.</small></div>';$('#placesList').innerHTML=html;document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>selectVolume(state.roots.find(r=>r.path===b.dataset.place)));$('#devicePlace')?.addEventListener('click',showDeviceChoice)}
  function selectVolume(r){if(!r)return;activeRoot=r;current=r.path;history=[r.path];folders=[];files=[];checked.clear();renderPlaces();renderVolumeTile(r);updateAdd()}
  function renderVolumeTile(r){$('#path').textContent=r.path;$('#up').disabled=true;$('#statusText').textContent=r.label;$('#itemCount').textContent='1 volume';$('#browserList').innerHTML=`<div class="pick49-head"><span></span><span>Name</span><span>Type</span></div><div class="pick49-row"><input class="pick49-check" type="checkbox" data-source-check="${esc(r.path)}" ${checked.has(r.path)?'checked':''}><button class="pick49-open volume" id="openVolume">▣ ${esc(r.label)} · ${esc(r.path)}</button><span class="pick49-kind">Volume</span></div>`;$('[data-source-check]').onchange=e=>togglePath(r.path,e.target.checked);$('#openVolume').onclick=()=>load(r.path)}
  async function load(path){if(!activeRoot)return;$('#browserList').innerHTML='<div class="pick49-empty">Loading…</div>';try{const d=await apiFs(path);current=d.path||path;folders=d.folders||[];files=d.files||[];$('#path').textContent=current;$('#up').disabled=history.length<=1;renderDirectory()}catch(e){$('#browserList').innerHTML=`<div class="pick49-empty"><strong>Unable to browse</strong>${esc(e.message)}</div>`;toast(e.message,'error')}}
  function renderDirectory(){const head='<div class="pick49-head"><span></span><span>Name</span><span>Type</span></div>';const fr=folders.map(n=>{const path=joinPath(current,n);return`<div class="pick49-row"><input class="pick49-check" type="checkbox" data-source-check="${esc(path)}" ${checked.has(path)?'checked':''}><button class="pick49-open" data-drill="${esc(n)}">▱ ${esc(n)}</button><span class="pick49-kind">Folder</span></div>`}).join('');const fi=files.map(n=>`<div class="pick49-row"><span></span><span class="pick49-open" style="font-weight:500">▧ ${esc(n)}</span><span class="pick49-kind">File</span></div>`).join('');$('#browserList').innerHTML=head+(fr+fi||'<div class="pick49-empty">This folder is empty.</div>');$('#statusText').textContent=current;$('#itemCount').textContent=`${folders.length+files.length} item${folders.length+files.length===1?'':'s'}`;document.querySelectorAll('[data-source-check]').forEach(c=>c.onchange=e=>togglePath(c.dataset.sourceCheck,e.target.checked));document.querySelectorAll('[data-drill]').forEach(b=>b.onclick=async()=>{const next=joinPath(current,b.dataset.drill);history.push(next);await load(next)})}
  function togglePath(path,on){if(on)checked.add(path);else checked.delete(path);updateAdd()}function updateAdd(){const b=$('#addChecked');b.disabled=checked.size===0;b.textContent=checked.size?`＋ Add to project (${checked.size})`:'＋ Add to project'}
  function renderSelected(){$('#selectedCount').textContent=String(staged.length);$('#selectedList').innerHTML=staged.length?staged.map((src,i)=>{const full=sourcePath(src),note=sourceNote(src);return`<div class="pick49-card" data-note-index="${i}" title="${esc(full)}"><div class="pick49-card-main"><div class="pick49-card-path">${esc(full)}</div><div class="pick49-card-note">${note?esc(note):'Add optional note…'}</div></div><button class="pick49-remove" data-remove-index="${i}" title="Remove source">×</button></div>`}).join(''):'<div class="pick49-empty"><strong>Nothing added yet</strong>Selected volumes and folders will appear here.</div>';document.querySelectorAll('[data-note-index]').forEach(card=>card.onclick=e=>{if(e.target.closest('[data-remove-index]'))return;editNote(Number(card.dataset.noteIndex))});document.querySelectorAll('[data-remove-index]').forEach(b=>b.onclick=e=>{e.stopPropagation();staged.splice(Number(b.dataset.removeIndex),1);renderSelected()})}
  function editNote(i){const src=staged[i],full=sourcePath(src),old=sourceNote(src);const note=prompt(`Optional note for:\n${full}`,old);if(note===null)return;if(typeof src==='string')staged[i]={...makePathSource(src),note:note.trim()};else staged[i]={...src,note:note.trim()};renderSelected()}
  $('#addChecked').onclick=()=>{let added=0;for(const path of checked){if(!stagedHasPath(path)){staged.push(makePathSource(path));added++}}checked.clear();updateAdd();if(activeRoot&&history.length===1)renderVolumeTile(activeRoot);else if(activeRoot)renderDirectory();renderSelected();if(added)toast(`${added} source${added===1?'':'s'} added to project draft.`)};$('#up').onclick=async()=>{if(history.length<=1){renderVolumeTile(activeRoot);return}history.pop();if(history.length===1){renderVolumeTile(activeRoot);return}await load(history[history.length-1])};$('#rescan').onclick=()=>{if(STATIC_PREVIEW){renderPlaces();return}if(activeRoot&&history.length>1)load(current);else checkServices().then(()=>{renderPlaces();if(activeRoot){const fresh=state.roots.find(r=>r.path===activeRoot.path);if(fresh)selectVolume(fresh)}})};$('#saveLocations').onclick=()=>{state.intake.sources=staged;close(true);renderIntake();toast(`${staged.length} location${staged.length===1?'':'s'} saved to draft.`)};$('#cancelLocations').onclick=()=>close(false);
  function showDeviceChoice(){activeRoot=null;checked.clear();updateAdd();document.querySelectorAll('.pick49-location').forEach(x=>x.classList.remove('active'));$('#path').textContent='This device';$('#up').disabled=true;$('#statusText').textContent='Browser-local storage';$('#itemCount').textContent='';$('#browserList').innerHTML='<div class="pick49-empty"><strong>This device</strong><button class="btn" id="chooseDeviceFolder">Choose folder…</button><div style="margin-top:8px">Browser security requires you to authorize a folder before it can be staged.</div></div>';$('#chooseDeviceFolder').onclick=pickLocalSourceAndStage}async function pickLocalSourceAndStage(){const src=await pickLocalDeviceSource();if(src&&!staged.some(s=>sourceKey(s)===sourceKey(src))){staged.push({...src,note:''});renderSelected();toast('Device folder added to project draft.')}}
  renderPlaces();renderSelected();updateAdd();
}
'''
